import{_ as t,o as d,c as o,a2 as s}from"./chunks/framework.il0noOp3.js";const u=JSON.parse('{"title":"Entra ID Inventory Modules","description":"Complete catalog of AzureScout Microsoft Entra ID inventory modules.","frontmatter":{"description":"Complete catalog of AzureScout Microsoft Entra ID inventory modules."},"headers":[],"relativePath":"reference/entra-modules.md","filePath":"reference/entra-modules.md"}'),i={name:"reference/entra-modules.md"};function a(n,e,r,c,l,h){return d(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="entra-id-inventory-modules" tabindex="-1">Entra ID Inventory Modules <a class="header-anchor" href="#entra-id-inventory-modules" aria-label="Permalink to &quot;Entra ID Inventory Modules&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>AzureScout&#39;s live Entra query catalog contains <strong>26 entries</strong>: 24 collected datasets and two disabled coverage records whose results no released collector consumes. It extracts tenant-wide identity and access-management data via Microsoft Graph, then retains every query outcome in the raw evidence ledger.</p><p>Run Entra-only extraction with:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Scope EntraOnly</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="how-entra-extraction-works" tabindex="-1">How Entra Extraction Works <a class="header-anchor" href="#how-entra-extraction-works" aria-label="Permalink to &quot;How Entra Extraction Works&quot;">​</a></h2><p>The <code>Start-AZSCEntraExtraction</code> function calls <code>Invoke-AZSCGraphRequest</code> for each Entra module, which:</p><ol><li>Authenticates via the Graph token obtained during login</li><li>Queries the relevant Microsoft Graph endpoint</li><li>Handles pagination (following <code>@odata.nextLink</code>)</li><li>Normalizes each result into a consistent resource shape:</li></ol><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Display Name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;TYPE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;microsoft.graph/users&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tenantId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;00000000-...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;properties&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h2 id="module-catalog" tabindex="-1">Module Catalog <a class="header-anchor" href="#module-catalog" aria-label="Permalink to &quot;Module Catalog&quot;">​</a></h2><p><code>Get-ScoutEntraQueryCatalog</code> (<code>src/collect/Get-ScoutEntraQueryCatalog.ps1</code>) is the single source of truth for these 26 catalog entries — <code>Start-AZSCEntraExtraction</code> runs every enabled entry, and the <code>-PermissionAudit</code> impact table is built by joining the same list against the collector manifests, so the two can no longer drift the way a hand-maintained second copy could.</p><table tabindex="0"><thead><tr><th>Module</th><th>Graph Endpoint</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td>Users</td><td><code>/users</code></td><td><code>User.Read.All</code></td><td>All user accounts (members and guests)</td></tr><tr><td>Groups</td><td><code>/groups</code></td><td><code>Group.Read.All</code></td><td>Security groups, Microsoft 365 groups, distribution lists</td></tr><tr><td>Applications</td><td><code>/applications</code></td><td><code>Application.Read.All</code></td><td>Application registrations (app IDs, credentials, API permissions)</td></tr><tr><td>Service Principals</td><td><code>/servicePrincipals</code></td><td><code>Application.Read.All</code></td><td>Enterprise applications and service principals</td></tr><tr><td>Managed Identities</td><td><code>/servicePrincipals</code> (filtered to <code>servicePrincipalType eq &#39;ManagedIdentity&#39;</code>)</td><td><code>Application.Read.All</code></td><td>Managed identities (system and user-assigned), as seen from the Entra service-principal object</td></tr><tr><td>Directory Roles</td><td><code>/directoryRoles</code></td><td><code>RoleManagement.Read.Directory</code></td><td>Activated directory roles and their members</td></tr><tr><td>PIM Assignments</td><td><code>/roleManagement/directory/roleAssignments</code></td><td><code>RoleManagement.Read.Directory</code></td><td>Privileged Identity Management (PIM) role assignments</td></tr><tr><td>Conditional Access Policies</td><td><code>/identity/conditionalAccess/policies</code></td><td><code>Policy.Read.All</code></td><td>Conditional Access policies</td></tr><tr><td>Authentication Method Registration Details</td><td><code>/reports/authenticationMethods/userRegistrationDetails</code></td><td><code>Reports.Read.All</code></td><td>Per-user MFA registration, capability, and registered methods</td></tr><tr><td>Sign-ins (last 30 days)</td><td><code>/auditLogs/signIns</code>, read as five week-long windows at the same time</td><td><code>AuditLog.Read.All</code></td><td>CA report-only impact, legacy authentication, and last-sign-in correlations</td></tr><tr><td>Directory Role Assignment Schedules</td><td><code>/roleManagement/directory/roleAssignmentSchedules</code></td><td><code>RoleAssignmentSchedule.Read.Directory</code></td><td>Active/permanent PIM schedules</td></tr><tr><td>Directory Role Eligibility Schedules</td><td><code>/roleManagement/directory/roleEligibilitySchedules</code></td><td><code>RoleEligibilitySchedule.Read.Directory</code></td><td>Eligible PIM schedules</td></tr><tr><td>Access Review Definitions</td><td><code>/identityGovernance/accessReviews/definitions</code></td><td><code>AccessReview.Read.All</code></td><td>Access-review definitions and instances</td></tr><tr><td>Organization</td><td><code>/organization</code></td><td><code>Directory.Read.All</code></td><td>Entra Connect sync state and last sync time</td></tr><tr><td>Named Locations</td><td><code>/identity/conditionalAccess/namedLocations</code></td><td><code>Policy.Read.All</code></td><td>Trusted locations for conditional access</td></tr><tr><td>Administrative Units</td><td><code>/directory/administrativeUnits</code></td><td><code>AdministrativeUnit.Read.All</code></td><td>Administrative units for delegated management</td></tr><tr><td>Domains</td><td><code>/domains</code></td><td><code>Domain.Read.All</code></td><td>Verified and unverified domains</td></tr><tr><td>Subscribed SKUs</td><td><code>/subscribedSkus</code></td><td><code>Organization.Read.All</code></td><td>License SKUs and service plan assignments</td></tr><tr><td>Cross-Tenant Access</td><td><code>/policies/crossTenantAccessPolicy/partners</code></td><td><code>Policy.Read.All</code></td><td>B2B cross-tenant access settings</td></tr><tr><td>External Identities</td><td><code>/policies/crossTenantAccessPolicy/default</code></td><td><code>Policy.Read.All</code></td><td>Default inbound/outbound B2B trust posture</td></tr><tr><td>Security Policies</td><td><code>/policies/authorizationPolicy</code></td><td><code>Policy.Read.All</code></td><td>Tenant authorization policy</td></tr><tr><td>Risky Users</td><td><code>/identityProtection/riskyUsers</code></td><td><code>IdentityRiskyUser.Read.All</code></td><td>Users flagged by Identity Protection (requires Entra ID P2)</td></tr><tr><td>Verified ID Authentication Method</td><td><code>/policies/authenticationMethodsPolicy/authenticationMethodConfigurations/VerifiableCredentials</code></td><td><code>Policy.Read.AuthenticationMethod</code></td><td>Tenant Verified ID authentication-method state and target groups</td></tr><tr><td>Verified ID Profiles</td><td><code>/identity/verifiedId/profiles</code></td><td><code>VerifiedId-Profile.Read.All</code></td><td>Configured Verified ID profiles</td></tr><tr><td>Identity Providers ⚠️</td><td><code>/identity/identityProviders</code></td><td><code>IdentityProvider.Read.All</code></td><td>Configured external/social identity providers</td></tr><tr><td>Security Defaults ⚠️</td><td><code>/policies/identitySecurityDefaultsEnforcementPolicy</code></td><td><code>Policy.Read.All</code></td><td>Tenant-wide security defaults enforcement state</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">⚠️ Collected, normalized, and read by nothing</p><p><code>Identity Providers</code> and <code>Security Defaults</code> remain in the catalog as disabled coverage records, so the inventory pass does not issue those two requests. <code>Identity Providers</code> has no released consumer. Security Defaults is read by the <strong>assessment</strong> collect instead: one direct request alongside the Conditional Access read described below, so a tenant protected only by Security Defaults is not mistaken for one with no MFA. <code>AuditLog.Read.All</code>, by contrast, now has multiple released consumers and is required for the last-30-day correlation datasets.</p></div><h2 id="how-the-assessments-read-conditional-access-and-directory-roles" tabindex="-1">How the assessments read Conditional Access and directory roles <a class="header-anchor" href="#how-the-assessments-read-conditional-access-and-directory-roles" aria-label="Permalink to &quot;How the assessments read Conditional Access and directory roles&quot;">​</a></h2><p>Conditional Access policies, named locations, Security Defaults and the directory role assignments are not only worksheets: they are collected into <code>collect.json</code> as <code>domains.identity.conditionalAccess</code> and <code>domains.identity.directoryRoles</code>, because Conditional Access decides who can sign in to Azure and under what proof, and identity items in the Azure assessments (MFA for Azure management, MFA for Azure Virtual Desktop, a Conditional Access baseline) are scored from it.</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>conditionalAccess.Collected</code> / <code>Reason</code></td><td>False, with the reason, when Graph was not read: <code>-Scope ArmOnly</code>, an offline render, no <code>Policy.Read.All</code>, no Entra ID P1, or the inventory pass reported the query failed (not retried). Rules gate on it and read <em>Not assessed</em>.</td></tr><tr><td><code>conditionalAccess.policies[]</code></td><td>Each policy&#39;s <code>id</code>, <code>displayName</code>, <code>state</code>, the raw <code>conditions</code> / <code>grantControls</code> / <code>sessionControls</code>, and booleans: <code>enabled</code>, <code>reportOnly</code>, <code>targetsAllUsers</code>, <code>targetsDirectoryRoles</code>, <code>targetsGuests</code>, <code>targetsAllApps</code>, <code>hasAppExclusions</code>, <code>targetsAzureManagement</code>, <code>targetsAdminPortals</code>, <code>targetsAvd</code>, <code>requiresMfa</code>, <code>blocks</code>, <code>blocksLegacyAuth</code>, <code>usesSignInRisk</code>, <code>usesUserRisk</code>, <code>usesLocations</code>, <code>requiresCompliantOrHybridDevice</code>, <code>hasExclusions</code>.</td></tr><tr><td><code>conditionalAccess.namedLocations[]</code></td><td>Type, trusted flag, and the <strong>number</strong> of IP ranges or countries. Address ranges are never kept.</td></tr><tr><td><code>conditionalAccess.securityDefaultsEnabled</code> / <code>securityDefaultsCoverage[]</code></td><td>True / false / null when unreadable; one policy-shaped row, present only when Security Defaults are on, saying what they enforce (MFA for all registered users, administrators and Azure management; legacy authentication blocked).</td></tr><tr><td><code>conditionalAccess.baselineAssessable</code></td><td>True only when Conditional Access was read <strong>and</strong> (Security Defaults state is known <strong>or</strong> at least one policy is enabled). Reading Security Defaults needs a role some readers lack; with no policy and Security Defaults unreadable, &quot;MFA is required by policy or by Security Defaults&quot; has no answer, so the rule that accepts either gates on this and reads <em>Not assessed</em> instead of <em>Fail</em>.</td></tr><tr><td><code>directoryRoles.assignments[]</code> / <code>eligibility[]</code></td><td>Principal id, principal type (looked up from the users, groups and service principals of the same pass), role name and scope. <code>eligibilityCollected</code> is false when <code>RoleEligibilitySchedule.Read.Directory</code> was not in the token: that means <em>not read</em>, never <em>nobody is eligible</em>.</td></tr></tbody></table><p><code>targetsAzureManagement</code> is strict: the <em>Windows Azure Service Management API</em> app (Azure Resource Manager, the portal, CLI and PowerShell) or all cloud apps. The <em>Microsoft Admin Portals</em> grouping covers the Azure portal but not CLI or PowerShell, so it sets <code>targetsAdminPortals</code> instead. <code>requiresMfa</code> and <code>requiresCompliantOrHybridDevice</code> are false when the grant operator is <code>OR</code> and another control could satisfy the policy, and <code>enabled</code> is false for a report-only policy.</p><h2 id="required-microsoft-graph-permissions" tabindex="-1">Required Microsoft Graph Permissions <a class="header-anchor" href="#required-microsoft-graph-permissions" aria-label="Permalink to &quot;Required Microsoft Graph Permissions&quot;">​</a></h2><blockquote><p><strong>&quot;I&#39;m a Global Administrator but the Entra modules still fail with 403 — why?&quot;</strong></p><p><strong>Global Administrator is an Entra directory <em>role</em>, not a Microsoft Graph API <em>scope</em>.</strong> Entra extraction uses the Graph token issued for the <strong>same Az context account and tenant</strong> that ARM collection uses (<code>Get-AzAccessToken</code>). That token only carries the delegated Graph scopes issued to the authentication client — your directory role does <strong>not</strong> widen those OAuth scopes. So an endpoint whose scope has not been consented returns <code>403 Forbidden</code> regardless of your role.</p></blockquote><p>To read every module above, the signed-in identity needs these <strong>delegated</strong> Microsoft Graph permissions carried by the selected identity&#39;s token (or application permissions on your own service principal) — see the Permission column in the <a href="#module-catalog">Module Catalog</a> above for which permission unlocks which module:</p><table tabindex="0"><thead><tr><th>Permission</th><th>Unlocks</th></tr></thead><tbody><tr><td><code>User.Read.All</code></td><td>Users</td></tr><tr><td><code>Group.Read.All</code></td><td>Groups</td></tr><tr><td><code>Application.Read.All</code></td><td>Applications, Service Principals, Managed Identities</td></tr><tr><td><code>RoleManagement.Read.Directory</code></td><td>Directory Roles, PIM Assignments</td></tr><tr><td><code>Policy.Read.All</code></td><td>Conditional Access Policies, Named Locations, Security Policies, Cross-Tenant Access, Security Defaults ⚠️</td></tr><tr><td><code>Reports.Read.All</code></td><td>Authentication Method Registration Details</td></tr><tr><td><code>AuditLog.Read.All</code></td><td>Sign-ins (last 30 days)</td></tr><tr><td><code>RoleAssignmentSchedule.Read.Directory</code></td><td>Directory Role Assignment Schedules</td></tr><tr><td><code>RoleEligibilitySchedule.Read.Directory</code></td><td>Directory Role Eligibility Schedules</td></tr><tr><td><code>AccessReview.Read.All</code></td><td>Access Review Definitions</td></tr><tr><td><code>Directory.Read.All</code></td><td>Organization / hybrid sync state</td></tr><tr><td><code>AdministrativeUnit.Read.All</code></td><td>Administrative Units</td></tr><tr><td><code>Domain.Read.All</code></td><td>Domains</td></tr><tr><td><code>Organization.Read.All</code></td><td>Subscribed SKUs</td></tr><tr><td><code>IdentityRiskyUser.Read.All</code></td><td>Risky Users (Identity Protection — also requires Entra ID P2)</td></tr><tr><td><code>IdentityProvider.Read.All</code> ⚠️</td><td>Identity Providers</td></tr><tr><td><code>Policy.Read.AuthenticationMethod</code></td><td>Verified ID Authentication Method</td></tr><tr><td><code>VerifiedId-Profile.Read.All</code></td><td>Verified ID Profiles</td></tr></tbody></table><p>⚠️ marks the two permissions behind the unconsumed queries — granting them satisfies the pre-flight but adds nothing to any report; see the warning above.</p><p>A broad <code>Directory.Read.All</code> grant also satisfies <code>User.Read.All</code>, <code>Group.Read.All</code> and <code>Application.Read.All</code> in practice, since it is a superset scope, but the table above is the minimum each query actually needs.</p><p>Grant/consent once (tenant admin), e.g.:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Re-establish the Az context for the exact account and tenant being scanned:</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Connect-AzAccount</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Tenant </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;tenant-id&gt;&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># For scopes the delegated token cannot carry, use AzureScout&#39;s service-principal parameters</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># with the required Microsoft Graph application permissions admin-consented in Entra ID.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Endpoints requiring a licensing tier you don&#39;t have (e.g. Risky Users without Entra ID P2) will still 403 — that is expected and is handled by <a href="#graceful-degradation">Graceful Degradation</a> below rather than aborting the run.</p><h2 id="data-normalization" tabindex="-1">Data Normalization <a class="header-anchor" href="#data-normalization" aria-label="Permalink to &quot;Data Normalization&quot;">​</a></h2><p>All collected Entra datasets produce output in the same normalized shape:</p><table tabindex="0"><thead><tr><th>Field</th><th>Source</th></tr></thead><tbody><tr><td><code>id</code></td><td>Graph object <code>id</code></td></tr><tr><td><code>name</code></td><td><code>displayName</code> (or most relevant name field)</td></tr><tr><td><code>TYPE</code></td><td>Synthetic type string (e.g., <code>microsoft.graph/users</code>)</td></tr><tr><td><code>tenantId</code></td><td>Tenant ID from the current session</td></tr><tr><td><code>properties</code></td><td>Full Graph object properties</td></tr></tbody></table><p>This normalization allows ARM and Entra resources to be processed by the same reporting pipeline.</p><h2 id="graceful-degradation" tabindex="-1">Graceful Degradation <a class="header-anchor" href="#graceful-degradation" aria-label="Permalink to &quot;Graceful Degradation&quot;">​</a></h2><p>If a single Entra query fails (e.g., insufficient permissions for Conditional Access policies), the module:</p><ul><li>Logs a warning</li><li>Continues with the remaining enabled queries</li><li>Returns partial results rather than failing entirely</li></ul><p>If <em>all</em> queries fail, the function returns an empty <code>EntraResources</code> collection.</p>`,34)])])}const g=t(i,[["render",a]]);export{u as __pageData,g as default};
